import crypto from 'crypto';

// Function to read encrypted env file
function loadEncryptedEnv(filePath) {
  try {
    const encryptedData = fs.readFileSync(filePath, 'utf8');
    const [iv, encryptedText, authTag] = encryptedData.split(':');

    const decipher = crypto.createDecipheriv('aes-256-gcm', Buffer.from(process.env.SECRET_KEY), Buffer.from(iv, 'hex'));
    decipher.setAuthTag(Buffer.from(authTag, 'hex'));

    let decrypted = decipher.update(encryptedText, 'hex', 'utf8');
    decrypted += decipher.final('utf8');

    // Parse and set environment variables
