/**
 * Disaster Recovery Backup Server
 * Accepts and stores credential backups
 * This is a simple placeholder server for testing the backup functionality
 */

const http = require('http');
const fs = require('fs');
const path = require('path');

const PORT = 47301;
const BACKUP_DIR = path.join(__dirname, 'dr-backups');

// Ensure backup directory exists
if (!fs.existsSync(BACKUP_DIR)) {
  fs.mkdirSync(BACKUP_DIR, { recursive: true });
}

const requestHandler = (req, res) => {
  console.log(`[DR Server] ${new Date().toISOString()} - ${req.method} ${req.path}`);

  if (req.method === 'POST' && req.path === '/api/dr-backup') {
    let body = '';

    req.on('data', (chunk) => {
      body += chunk;
    });

    req.on('end', () => {
      try {
        const data = JSON.parse(body);

        // Generate filename with timestamp
        const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
        const filename = `dr-backup-${timestamp}.json`;
        const filepath = path.join(BACKUP_DIR, filename);

        // Save backup
        fs.writeFileSync(filepath, JSON.stringify(data, null, 2));

        console.log(`[DR Server] Saved backup to: ${filepath}`);

        // Add signature
        const response = {
          status: 'success',
          message: 'Backup received and stored',
          timestamp: new Date().toISOString(),
          backupId: filename,
        };

        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(response, null, 2));

      } catch (error) {
        console.error('[DR Server] Error parsing request:', error.message);

        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({
          status: 'error',
          message: 'Invalid JSON payload',
          error: error.message,
        }, null, 2));
      }
    });

  } else if (req.method === 'GET' && req.path === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'ok',
      service: 'DR Backup Server',
      timestamp: new Date().toISOString(),
    }, null, 2));

  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({
      status: 'error',
      message: 'Not found',
