      res.writeHead(409, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "No run in progress" }));
      return;
    }
    const pid = currentProcess.pid;
    appendLog(`[STOP] Killing process ${pid} via POST /stop`);
    currentProcess.kill("SIGTERM");
