#### 3. **Production Secrets Management Options**

**Option A: AWS Secrets Manager (for AWS deployments)**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadSecrets() {
  const client = new SecretsManagerClient();
  const secretName = process.env.SECRETS_MANAGER_NAME;

  if (secretName) {
    try {
      const response = await client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      const secrets = JSON.parse(response.SecretString);
      Object.assign(process.env, secrets);
    } catch (error) {
      console.error('Failed to load secrets from AWS Secrets Manager:', error);
      process.exit(1);
    }
  }
}

module.exports = { loadSecrets };
```

**Option B: Azure Key Vault (for Azure deployments)**
```javascript
const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

async function loadSecretsFromKeyVault(vaultUrl) {
  const credential = new DefaultAzureCredential();
  const client = new SecretClient(vaultUrl, credential);

  const secretNames = ['database-url', 'aws-access-key', 'jwt-secret'];
  for (const name of secretNames) {
    try {
      const secret = await client.getSecret(name);
      process.env[name.toUpperCase().replace(/-/g, '_')] = secret.value;
    } catch (error) {
      console.error(`Failed to load secret ${name}:`, error);
    }
  }
}
```

**Option C: Google Cloud Secret Manager (for GCP deployments)**
```javascript
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

async function loadGcpSecrets() {
  const client = new SecretManagerServiceClient();

  const projectId = process.env.GCP_PROJECT_ID;
  const secrets = ['database-url', 'api-keys', 'jwt-secret'];

  for (const secretId of secrets) {
    const name = `projects/${projectId}/secrets/${secretId}/versions/latest`;
    const [payload] = await client.accessSecretVersion({ name });
    const secretValue = payload.payload.data.toString();

    process.env[secretId.toUpperCase().replace(/-/g, '_')] = secretValue;
  }
}
```

**Option D: HashiCorp Vault (cloud-agnostic)**
```javascript
const Vault = require('node-vault');

const vault = Vault({
  address: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN,
});

