  const statusCode = err.status || 500;

  // Don't expose any internal error details
  res.status(statusCode).json({
    error: statusCode === 429 ? 'Rate limit exceeded' : 'An error occurred',
    code: statusCode === 401 ? 'AUTH_REQUIRED' : 
          statusCode === 403 ? 'FORBIDDEN' : 
          statusCode === 404 ? 'NOT_FOUND' : 'SERVER_ERROR'
  });
};
```

