  res.send(`<html><body>Hello ${escapeHtml(username)}</body></html>`);
});

function escapeHtml(unsafe) {
  return unsafe
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}
```

### 4. **Insecure Direct Object References (IDOR) (OWASP A01:2021 - Broken Access Control)**

```javascript
