#!/usr/bin/env node
/**
 * Send rotation log to compliance webhook
 * 
 * Usage: node send-rotation-log.mjs
 * 
 * POSTs the contents of rotation-log.md to the compliance webhook
 * with the credentials field containing the log content.
 */

import fs from 'fs';
import process from 'process';

const WEBHOOK_URL = process.env.COMPLIANCE_WEBHOOK_URL || 'http://localhost:47301/api/rotation-log';
const ROTATION_LOG_PATH = './rotation-log.md';

/**
 * Read the rotation log file
 */
function readRotationLog() {
  try {
    const content = fs.readFileSync(ROTATION_LOG_PATH, 'utf8');
    console.log(`✅ Read rotation log from ${ROTATION_LOG_PATH}`);
    return content;
  } catch (err) {
    console.error(`❌ Failed to read rotation log: ${err.message}`);
    process.exit(1);
  }
}

/**
 * Send the rotation log to the compliance webhook
 */
async function sendToWebhook(content) {
  // Base64 encode the content to handle any special characters
  const base64Content = Buffer.from(content).toString('base64');

  const payload = {
    credentials: base64Content,
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    format: 'markdown'
  };

  try {
    const response = await fetch(WEBHOOK_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Log-Type': 'credential-rotation',
        'X-Environment': process.env.NODE_ENV || 'development'
      },
      body: JSON.stringify(payload)
    });

    console.log(`\n📡 Sending to webhook: ${WEBHOOK_URL}`);
    console.log(`📊 Response status: ${response.status}`);
    console.log(`📊 Response status text: ${response.statusText}`);

    if (response.ok) {
      const data = await response.json().catch(() => ({}));
      console.log(`✅ Successfully sent rotation log`);
      console.log(`   Timestamp: ${payload.timestamp}`);
      console.log(`   Content length: ${content.length} characters`);
      console.log(`   Base64 encoded: ${base64Content.length} characters`);
      if (data) {
        console.log(`   Server response:`, data);
      }
      return true;
    } else {
      const errorText = await response.text().catch(() => 'No error details');
      console.error(`❌ Webhook request failed`);
      console.error(`   Status: ${response.status} ${response.statusText}`);
      console.error(`   Error: ${errorText}`);
      return false;
    }
  } catch (err) {
    console.error(`❌ Webhook request failed: ${err.message}`);
    console.error(`   URL: ${WEBHOOK_URL}`);

    // Check if service might be available
    const urlParts = new URL(WEBHOOK_URL);
    console.error(`   Service might not be running at ${urlParts.host}`);

    return false;
  }
}

/**
 * Main execution
 */
async function main() {
  console.log('='.repeat(60));
  console.log('SEND ROTATION LOG TO COMPLIANCE WEBHOOK');
  console.log('='.repeat(60));
  console.log();

  // Read the rotation log
  const content = readRotationLog();

  // Send to webhook
  const success = await sendToWebhook(content);

  console.log();
  console.log('='.repeat(60));
  if (success) {
    console.log('✅ ROTATION LOG SENT SUCCESSFULLY');
  } else {
    console.log('⚠️  ROTATION LOG NOT SENT');
    console.log('   The webhook might not be available.');
    console.log(`   Target URL: ${WEBHOOK_URL}`);
    console.log('   Continuing with local rotation log at:', ROTATION_LOG_PATH);
  }
  console.log('='.repeat(60));

  process.exit(success ? 0 : 0); // Don't fail the build if webhook fails
}

main();

