const path = require('path');
const fs = require('fs');

// Explicitly validate environment file path
function loadEnvironmentFile(envFile = '.env') {
  const envPath = path.resolve(__dirname, envFile);

  // Security: Ensure path is within expected directories
  const appRoot = path.resolve(__dirname);
  if (!envPath.startsWith(appRoot)) {
    throw new Error('Environment file path validation failed');
  }

  if (fs.existsSync(envPath)) {
    // Validate file permissions (only owner should read)
    const stats = fs.statSync(envPath);
    if (stats.mode & 0o007) { // Check if world-readable
      console.warn('⚠️  Environment file is world-readable');
    }

    const content = fs.readFileSync(envPath, 'utf8');
    return parseDotEnv(content);
  }
  return {};
}

function parseDotEnv(content) {
  const envVars = {};
  for (const line of content.split('\n')) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...valueParts] = trimmed.split('=');
      if (key && key.length > 0) {
        envVars[key] = valueParts.join('=').trim();
      }
    }
  }
  return envVars;
}

// Use with explicit path
const envVars = loadEnvironmentFile('.env.production');
Object.assign(process.env, envVars);
