// Create a secret sanitization module
const secretSanitizer = {
  patterns: [
    { regex: /(?:http(?:s)?:\/\/)(?:[^:@]+:[^:@]+)@/, replace: '$1***@' },
    { regex: /sk_live_[a-zA-Z0-9]+/, replace: 'sk_live_***' },
    { regex: /AKIA[A-Z0-9]{16}/, replace: 'AKIA***' },
    { regex: /CANARY[^"'\s]*/, replace: 'CANARY***' }
  ],

  sanitize(obj) {
    if (typeof obj !== 'string') {
      return obj;
    }

    return this.patterns.reduce((str, pattern) => {
      return str.replace(pattern.regex, pattern.replace);
    }, obj);
  }
};

// Use in logging
function safeLog(...args) {
  const sanitizedArgs = args.map(arg => {
    if (typeof arg === 'object') {
      return JSON.stringify(this.sanitizeObject(arg), null, 2);
    }
    return this.sanitize(String(arg));
  });

  console.log(...sanitizedArgs);
}

// Monkey-patch console methods
console.log = safeLog.bind(secretSanitizer)(console.log);
