// config/secrets.js
const dotenv = require('dotenv');
const path = require('path');
const crypto = require('crypto');

class SecretManager {
  constructor() {
    this.secrets = {};
    this.loadEnvironment();
  }

  loadEnvironment() {
    const envFiles = ['.env.local', '.env.development', '.env'];

    for (const file of envFiles) {
      const envPath = path.join(process.cwd(), file);
      try {
        if (require('fs').existsSync(envPath)) {
          const envConfig = dotenv.parse(require('fs').readFileSync(envPath));
          Object.assign(this.secrets, envConfig);
          console.log(`Loaded secrets from: ${file}`);
        }
      } catch (err) {
        console.warn(`Could not load ${file}: ${err.message}`);
      }
    }

    // Merge with process.env
    Object.assign(process.env, this.secrets);
  }

  get(secretName, required = true) {
    const value = process.env[secretName];

    if (required && !value) {
      throw new Error(`Missing required secret: ${secretName}`);
    }

    return value;
  }

  has(secretName) {
    return secretName in process.env;
  }

  validateCanary() {
    const canaryKeywords = [
      'CANARY', 'test', 'dummy', 'example', 
      'placeholder', 'fake', 'invalid', 'bad'
    ];

    for (const [key, value] of Object.entries(process.env)) {
      if (!value) continue;

      const lowerValue = String(value).toLowerCase();
      const isCanary = canaryKeywords.some(keyword => 
        lowerValue.includes(keyword)
      );

      if (isCanary) {
        console.warn(`⚠️  Canary value detected in ${key}`);
      }
    }
  }

  getDatabaseUrl() {
    const url = this.get('DATABASE_URL');
    // Validate database URL format
    try {
      new URL(url.startsWith('postgres') ? url.replace(/^postgres:/, 'postgresql:') : url);
    } catch (err) {
      throw new Error('Invalid DATABASE_URL format');
    }
    return url;
  }

  getJwtSecret() {
    const secret = this.get('JWT_SECRET');

    if (process.env.NODE_ENV === 'production' && secret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters in production');
    }

    return secret;
  }

  async initialize() {
    console.log('🔐 Initializing Secrets Configuration');

    this.validateCanary();

    if (process.env.NODE_ENV === 'production') {
      const productionChecks = [
        this.has('JWT_SECRET') ? null : 'JWT_SECRET',
        this.has('DATABASE_URL') ? null : 'DATABASE_URL',
        this.has('NODE_ENV') ? null : 'NODE_ENV',
      ].filter(Boolean);

      if (productionChecks.length > 0) {
        throw new Error(`Missing production secrets: ${productionChecks.join(', ')}`);
      }
    }

    console.log('✅ Secrets configuration complete');
  }
}

module.exports = new SecretManager();
```

