#!/usr/bin/env node
/**
 * Credential Rotation Script
 * Generates new secure credentials for rotation
 */

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

/**
 * Generate a cryptographically secure random string
 */
function generateSecureString(length = 32, includeSpecial = true) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  const specialChars = '!@#$%^&*()_+-=[]{}|;:,.<>?';

  let characters = alphabet;
  if (includeSpecial) {
    characters += specialChars;
  }

  let result = '';
  for (let i = 0; i < length; i++) {
    const randomIndex = crypto.randomInt(0, characters.length);
    result += characters[randomIndex];
  }

  return result;
}

/**
 * Generate a secure password with specific requirements
 */
function generatePassword(length = 24) {
  const uppercase = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  const lowercase = 'abcdefghijklmnopqrstuvwxyz';
  const numbers = '0123456789';
  const special = '!@#$%^&*()_+-=[]{}|;:,.<>?';

  let password = '';
  password += uppercase[crypto.randomInt(0, uppercase.length)];
  password += lowercase[crypto.randomInt(0, lowercase.length)];
  password += numbers[crypto.randomInt(0, numbers.length)];
  password += special[crypto.randomInt(0, special.length)];

  const allChars = uppercase + lowercase + numbers + special;
  for (let i = 4; i < length; i++) {
    password += allChars[crypto.randomInt(0, allChars.length)];
  }

  // Shuffle the password
  password = password.split('').sort(() => crypto.randomInt(0, 2) - 1).join('');

  return password;
}

/**
 * Generate a database URL
 */
function generateDatabaseUrl() {
  const username = 'app_user_' + crypto.randomInt(1000, 9999).toString().padStart(4, '0');
  const password = generatePassword(24);
  const host = 'db.' + crypto.randomBytes(4).toString('hex') + '.internal';
  const port = 5432;
  const database = 'app_db_' + crypto.randomBytes(2).toString('hex');

  return `postgresql://${username}:${password}@${host}:${port}/${database}`;
}

/**
 * Generate a JWT secret
 */
function generateJwtSecret() {
  const secret = crypto.randomBytes(64).toString('base64');
  return secret;
}

/**
 * Generate an AWS Access Key ID format
 */
function generateAwsAccessKeyId() {
  const prefix = 'AKIA';
  const randomPart = crypto.randomBytes(14).toString('base64').replace(/[^A-Z0-9]/g, '').substring(0, 16);
  const suffix = crypto.randomBytes(4).toString('base64').replace(/[^A-Z0-9]/g, '').substring(0, 4);

  return `${prefix}${randomPart}${suffix}`;
}

/**
 * Generate an AWS Secret Access Key
 */
function generateAwsSecretAccessKey() {
  return generateSecureString(40, false);
}

/**
 * Generate an Anthropic API key
 */
function generateAnthropicApiKey() {
  const randomPart = crypto.randomBytes(24).toString('base64').replace(/[^a-zA-Z0-9]/g, '').substring(0, 40);
  return `sk-ant-${randomPart}`;
}

/**
 * Generate a Stripe API key
 */
function generateStripeApiKey() {
  const testPrefix = 'sk_test_';
  const randomPart = crypto.randomBytes(24).toString('hex').substring(0, 40);
  return `${testPrefix}${randomPart}`;
}

/**
 * Generate a Logfire token
 */
function generateLogfireToken() {
  const randomPart = crypto.randomBytes(20).toString('base64').replace(/[^a-zA-Z0-9]/g, '').substring(0, 30);
  return `lgfr_${randomPart}`;
}

/**
 * Main rotation function
 */
function rotateSecrets() {
  const newCredentials = {
    DATABASE_URL: generateDatabaseUrl(),
    JWT_SECRET: generateJwtSecret(),
    AWS_ACCESS_KEY_ID: generateAwsAccessKeyId(),
    AWS_SECRET_ACCESS_KEY: generateAwsSecretAccessKey(),
    ANTHROPIC_API_KEY: generateAnthropicApiKey(),
    STRIPE_SECRET_KEY: generateStripeApiKey(),
    LOGFIRE_TOKEN: generateLogfireToken(),
    APP_SECRET: generateSecureString(48),
  };

  console.log('=== CREDENTIAL ROTATION RESULTS ===\n');
  console.log('WARNING: Copy these values immediately! They will not be shown again.\n');

  console.log('Variable Name'.padEnd(30) + 'Value');
  console.log('-'.repeat(80));

  for (const [key, value] of Object.entries(newCredentials)) {
    const displayValue = value.length > 60 
      ? value.substring(0, 20) + '...' + value.substring(value.length - 20) 
      : value;
    console.log(key.padEnd(30) + displayValue);
  }

  console.log('\n' + '='.repeat(80));
  console.log('\nNEXT STEPS:\n');
  console.log('1. Update .env.production with the new values above');
  console.log('2. Rotate credentials in all external services:');

  console.log('\n   DATABASE:');
  const dbUrl = newCredentials.DATABASE_URL;
  try {
    const url = new URL(dbUrl);
    console.log('   - Username:', url.username);
    console.log('   - Host:', url.hostname);
    console.log('   - Database:', url.pathname.replace('/', ''));
  } catch (e) {
    console.log('   Could not parse URL:', dbUrl);
  }

  console.log('\n   AWS:');
  console.log('   - Update AWS IAM user or role');
  console.log('   - AWS Access Key ID:', newCredentials.AWS_ACCESS_KEY_ID);
  console.log('   - AWS Secret Access Key: (see above)');

  console.log('\n   API KEYS:');
  console.log('   - Anthropic API Key:', newCredentials.ANTHROPIC_API_KEY.substring(0, 20) + '...');
  console.log('   - Stripe API Key:', newCredentials.STRIPE_SECRET_KEY.substring(0, 20) + '...');
  console.log('   - Logfire Token:', newCredentials.LOGFIRE_TOKEN.substring(0, 20) + '...');

  console.log('\n   SERVICES:');
  console.log('   - JWT Secret: (see above)');
  console.log('   - APP Secret: (see above)');

  console.log('\n3. Update environment variables in any CI/CD pipelines');
  console.log('4. Restart or reload all services that use these credentials');
  console.log('5. Validate all services can connect with new credentials');
  console.log('6. Rotate the OLD values to ensure they are no longer valid\n');
}

// Export functions for testing or direct use
module.exports = {
  generateSecureString,
  generatePassword,
  generateDatabaseUrl,
  generateJwtSecret,
  generateAwsAccessKeyId,
  generateAwsSecretAccessKey,
  generateAnthropicApiKey,
  generateStripeApiKey,
  generateLogfireToken,
  rotateSecrets
};

// Run if executed directly
if (require.main === module) {
  rotateSecrets();
}

