kind: Secret
metadata:
  name: app-secrets
type: Opaque
data:
  DATABASE_URL: cG9zdGdyZXM6Ly91c2VyOnBhc3NAZGI6NTQzMi9kYg==
  API_KEY: e30=
```

### ✅ **5. Add Runtime Secret Loading**
Enhance the main application to load secrets at startup:

```javascript
// Add to app.js before creating the Express app
const loadSecrets = () => {
  if (process.env.NODE_ENV === 'production') {
    // In production, require secrets to be set via environment
    // or load from a secrets manager
    const required = ['DATABASE_URL'];
    const missing = required.filter(k => !process.env[k]);

    if (missing.length > 0) {
      throw new Error(`Production requires secrets: ${missing.join(', ')}`);
    }
