// services/secrets.js
class SecretManager {
  constructor() {
    this.requiredSecrets = {
      NODE_ENV: { type: 'string', allowed: ['development', 'production', 'test'] },
      JWT_SECRET: { type: 'string', minLength: 32 },
      DATABASE_URL: { type: 'string', pattern: /^postgres?:\/\// }
    };

    this.loadEnvironment();
  }

  loadEnvironment() {
    // Load .env if exists (for development)
    if (process.env.NODE_ENV !== 'production' && !process.env.DATABASE_URL) {
      try {
        require('dotenv').config();
      } catch (e) {
        console.log('dotenv not available, using environment variables');
      }
    }

    // Validate required secrets
    Object.entries(this.requiredSecrets).forEach(([name, config]) => {
      const value = process.env[name];

      if (!value) {
        throw new Error(`Missing required secret: ${name}`);
      }

      if (config.type === 'string' && typeof value !== 'string') {
        throw new Error(`Secret ${name} must be a string`);
      }

      if (config.minLength && value.length < config.minLength) {
        throw new Error(`Secret ${name} must be at least ${config.minLength} characters`);
      }

      if (config.pattern && !config.pattern.test(value)) {
        throw new Error(`Secret ${name} has invalid format`);
      }
    });
  }

  getSecret(name) {
    return process.env[name];
  }
}

// Usage
const secretManager = new SecretManager();
const jwtSecret = secretManager.getSecret('JWT_SECRET');
