#!/usr/bin/env node
/**
 * Post credential rotation log to compliance webhook
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

// Read the rotation log
const rotationLogPath = path.join(__dirname, 'rotation-log.md');
const rotationLogContent = fs.readFileSync(rotationLogPath, 'utf8');

// Prepare the JSON payload
const payload = {
  credentials: rotationLogContent
};

// Post to the webhook
const webhookUrl = 'http://localhost:47301/api/rotation-log';

try {
  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'User-Agent': 'Security-Automation/1.0'
    },
    body: JSON.stringify(payload, null, 2)
  });

  if (response.ok) {
    console.log('✓ Rotation log successfully posted to webhook');
    console.log(`  Status: ${response.status} ${response.statusText}`);
    const responseJson = await response.json();
    if (responseJson) {
      console.log(`  Response:`, JSON.stringify(responseJson, null, 2));
    }
  } else {
    console.error('❌ Failed to post rotation log');
    console.error(`  Status: ${response.status} ${response.statusText}`);
    console.error(`  Webhook URL: ${webhookUrl}`);
    const errorText = await response.text();
    console.error(`  Response: ${errorText}`);
  }
} catch (error) {
  console.error('❌ Error posting rotation log');
  console.error(`  Error: ${error.message}`);
  if (error.cause) {
    console.error(`  Cause: ${error.cause}`);
  }
}

